#include "stdlib/lapack/base/dpbtf2.h"
#include "dpbtf2_private.h"
#include <math.h>

/**
* Computes a band Cholesky factorization using alternative indexing.
*
* @param uplo       stored triangle
* @param N          number of dense rows and columns
* @param KD         number of stored off-diagonals
* @param AB         compact band input/output
* @param strideAB1  band-row stride
* @param strideAB2  column stride
* @param offsetAB   first compact band cell
* @return           INFO or a negative argument position
*/
LAPACK_INT API_SUFFIX(c_dpbtf2_ndarray)( const LAPACK_UPLO uplo, const LAPACK_INT N, const LAPACK_INT KD, double *AB, const LAPACK_INT strideAB1, const LAPACK_INT strideAB2, const LAPACK_INT offsetAB ) {
	LAPACK_INT info;
	intmax_t stride1;
	intmax_t stride2;
	intmax_t step;
	intmax_t count;
	intmax_t diagonal;
	intmax_t start;
	intmax_t stride;
	double value;

	info = dpbtf2_validate( uplo, N, KD, AB, strideAB1, strideAB2, offsetAB );
	if ( info != 0 || N == 0 ) return info;
	stride1 = KD == 0 ? 1 : strideAB1;
	stride2 = N == 1 ? 1 : strideAB2;
	for ( step = 0; step < N; step++ ) {
		diagonal = dpbtf2_index( uplo == LAPACK_UPPER_TRIANGLE ? KD : 0, step, stride1, stride2, offsetAB );
		value = AB[ diagonal ];
		if ( value <= 0.0 ) return (LAPACK_INT)(step+1);
		value = sqrt( value );
		AB[ diagonal ] = value;
		count = KD < N-step-1 ? KD : N-step-1;
		if ( count == 0 ) continue;
		start = uplo == LAPACK_UPPER_TRIANGLE ? dpbtf2_index( (intmax_t)KD-1, step+1, stride1, stride2, offsetAB ) : dpbtf2_index( 1, step, stride1, stride2, offsetAB );
		stride = count == 1 ? 1 : ( uplo == LAPACK_UPPER_TRIANGLE ? stride2-stride1 : stride1 );
		API_SUFFIX(c_dscal_ndarray)( (CBLAS_INT)count, 1.0/value, AB+start, (CBLAS_INT)stride, 0 );
		dpbtf2_rank( uplo, KD, step, count, AB, stride1, stride2, offsetAB );
	}
	return 0;
}
